#include <bits/stdc++.h>
using namespace std;

class Solution { public: int maximumScore(vector<int>& scores, vector<vector<int>>& edges) { int n=scores.size(),ans=-1; vector<vector<int>> adj(n); for(auto &e:edges){adj[e[0]].push_back(e[1]);adj[e[1]].push_back(e[0]);} for(int i=0;i<n;++i){auto &a=adj[i]; sort(a.begin(),a.end(),[&](int x,int y){return scores[x]>scores[y];}); if(a.size()>3)a.resize(3);} for(auto &e:edges){int u=e[0],v=e[1];for(int a:adj[u])for(int b:adj[v])if(a!=v&&b!=u&&a!=b)ans=max(ans,scores[a]+scores[u]+scores[v]+scores[b]);}return ans;} };
